CREATE TABLE IF NOT EXISTS ticket_order (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,session_id CHAR(36) NOT NULL,seat_ids TEXT NOT NULL,idempotency_key VARCHAR(128) NOT NULL UNIQUE,status VARCHAR(32) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
